import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.DncwoWA8.js";const r="/projects/ai-skills/diagrams/required-dependencies.svg",k=JSON.parse('{"title":"Skill dependencies and project workflows","description":"","frontmatter":{"title":"Skill dependencies and project workflows"},"headers":[],"relativePath":"reference/relationships.md","filePath":"reference/relationships.md"}'),o={name:"reference/relationships.md"};function n(l,e,d,c,p,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="skill-dependencies-and-project-workflows" tabindex="-1">Skill dependencies and project workflows <a class="header-anchor" href="#skill-dependencies-and-project-workflows" aria-label="Permalink to &quot;Skill dependencies and project workflows&quot;">​</a></h1><p>A line between two skill names can mean different things. Treating every useful combination as a prerequisite produces unnecessary installations and unsafe automatic follow-up work.</p><h2 id="required-instruction-dependencies" tabindex="-1">Required instruction dependencies <a class="header-anchor" href="#required-instruction-dependencies" aria-label="Permalink to &quot;Required instruction dependencies&quot;">​</a></h2><p><code>A → B</code> in this map means: resolve the installed instructions for <strong>B before applying A</strong>. It does not mean execute B after A. The catalog currently records <strong>6 edges</strong>, checked against the local <code>requires</code> frontmatter.</p><p><img src="'+r+'" alt="Six declared instruction dependencies, directed from each requesting skill to its required instructions."></p><p><a href="/projects/ai-skills/diagrams/required-dependencies.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/required-dependencies.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/required-dependencies.json">Editable candidate</a></p><table tabindex="0"><thead><tr><th>Requesting skill</th><th>Required instructions</th></tr></thead><tbody><tr><td><a href="/projects/ai-skills/skills/cleanup-workspaces.html"><code>cleanup-workspaces</code></a></td><td><a href="/projects/ai-skills/skills/isolated-workspace.html"><code>isolated-workspace</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/coding-with-rules.html"><code>coding-with-rules</code></a></td><td><a href="/projects/ai-skills/skills/coding.html"><code>coding</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/grill-me.html"><code>grill-me</code></a></td><td><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/initiative.html"><code>initiative</code></a></td><td><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/research.html"><code>research</code></a></td><td><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a></td></tr><tr><td><a href="/projects/ai-skills/skills/specify.html"><code>specify</code></a></td><td><a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a></td></tr></tbody></table><p>The <code>requires</code> declaration is a project extension, not a standard Agent Skills field or a native loader guarantee. Resolve recursively in array order, stop on missing requirements or cycles, and obtain approved setup. Direct Skills CLI installation does not automatically install this closure. If a selected skill or required instructions are missing, stop the task and ask the user to install them. Resume only after installation is confirmed and availability is verified.</p><h2 id="installation-prerequisites" tabindex="-1">Installation prerequisites <a class="header-anchor" href="#installation-prerequisites" aria-label="Permalink to &quot;Installation prerequisites&quot;">​</a></h2><p>These are things that must exist before installation or use: an approved source, a trusted checkout, a parser dependency, filesystem support, or other documented setup. Do not turn a tool prerequisite into a new skill dependency. Installation still needs applicable approval.</p><h2 id="runtime-and-harness-requirements" tabindex="-1">Runtime and harness requirements <a class="header-anchor" href="#runtime-and-harness-requirements" aria-label="Permalink to &quot;Runtime and harness requirements&quot;">​</a></h2><p>A skill can need Bun, Node.js, a local browser, a rendering CLI, or authorized subagent tools without requiring another skill. The profile&#39;s runtime section comes from the catalog; the linked authoritative instructions define the complete contract. A supported harness name does not prove those capabilities are present.</p><h2 id="project-selected-workflows" tabindex="-1">Project-selected workflows <a class="header-anchor" href="#project-selected-workflows" aria-label="Permalink to &quot;Project-selected workflows&quot;">​</a></h2><p>Portable skill packages and individual profiles name only their declared required skills. A user or project may select additional standalone skills in a separate workflow guide. Such a choice does not change a skill&#39;s dependency declaration or authorize later work.</p><h2 id="phase-handoffs-and-owner-decisions" tabindex="-1">Phase handoffs and owner decisions <a class="header-anchor" href="#phase-handoffs-and-owner-decisions" aria-label="Permalink to &quot;Phase handoffs and owner decisions&quot;">​</a></h2><p>A workflow arrow suggests a later phase; it is not a new <code>requires</code> edge or permission to continue. Research can end at findings, planning at a task list, scaffolding at a skeleton, and review at findings. Approval gates remain on the operation they protect. A draft cannot approve itself, and a successful review cannot authorize a merge or release.</p><p><a href="/projects/ai-skills/workflows/">Choose a workflow</a> or <a href="/projects/ai-skills/skills/">inspect an individual skill</a>.</p>',17)])])}const f=s(o,[["render",n]]);export{k as __pageData,f as default};
